using System;using System.Linq;
namespace V15Voice {public sealed partial class VoiceRenderReport {
 public void TargetAttempt(VoiceReportAttempt a){lock(sync){Append("TXT đích: đã thử "+F(a.Speed)+"x; đo "+F(a.Measured)+"s; đích "+F(a.Target)+"s; dư/thiếu "+F(a.Measured-a.Target)+"s");}}
 public void TargetDone(double speed){lock(sync){foreach(var u in Units){u.Speed=speed;u.Status="Đã xuất cùng TXT đích; chưa đo mốc sau căn từng câu";}}}
 void TargetReport(Action<string> line){if(options.TargetSeconds==0&&String.IsNullOrEmpty(options.TargetRaw))return;line("");line("TXT · CĂN THỜI LƯỢNG ĐÍCH · toàn bài");line("Yêu cầu nhập: "+options.TargetRaw+"; đích "+F(options.TargetSeconds>0?(double?)options.TargetSeconds:null)+"s; mức căn TXT tối đa ±"+F(options.TargetChange*100)+"% (giao với giới hạn tốc độ/căn nhịp đã đặt)");var r=options.TargetResult;if(r==null){line("Chưa có số đo TXT đích; kiểm tra lỗi đầu vào hoặc bước hiện tại.");return;}line("Gốc đã đo (gồm lời/nghỉ/hơi thở): "+F(r.Natural)+"s; đích "+F(r.Target)+"s; giới hạn áp dụng riêng TXT: "+F(r.Minimum)+"–"+F(r.Maximum)+"x");line("Tốc độ ước tính trước giới hạn: "+F(r.Required)+"x; tốc độ lần cuối đã đo: "+F(r.Speed)+"x");if(r.Speed.HasValue)line(Change(r.Speed.Value));line("Audio lần cuối trước hiệu chỉnh đuôi: "+F(r.Measured)+"s; chênh đo-đích: "+F(r.Measured.HasValue?r.Measured-r.Target:(double?)null)+"s; bù đuôi "+F(r.Fitted?(double?)r.Adjustment:null)+"s");line("Kết quả: "+r.Describe());line("Chỉ bù sai số tối đa 20 ms; chỉ cắt phần đuôi đã kiểm tra là im lặng. Không chèn im lặng dài và không cắt lời để ép đủ thời lượng.");line("Bảng đơn vị lời đọc giữ mốc TRƯỚC căn toàn bài, không phải mốc WAV cuối. Không suy ra mốc sau căn từng câu bằng tỷ lệ.");Attempts(line,r.Attempts);if(r.Reason.Length>0)line("Lý do: "+r.Reason);}
}}
